"use client";

import React, { useEffect, useState, useRef } from "react";
import { useRouter } from "next/navigation";
import { useAuth } from "@/contexts/AuthContext";
import { useSocket } from "@/contexts/SocketContext";
import api from "@/services/api";
import dayjs from "dayjs";
import isToday from "dayjs/plugin/isToday";
import isYesterday from "dayjs/plugin/isYesterday";
import relativeTime from "dayjs/plugin/relativeTime";
import MessageBubble from "@/components/MessageBubble";

dayjs.extend(isToday);
dayjs.extend(isYesterday);
dayjs.extend(relativeTime);

const EMOJI_LIST = ["😀", "😂", "😍", "😢", "👍", "🙏", "🎉", "💬"];
const STUN_CONFIG = { iceServers: [{ urls: "stun:stun.l.google.com:19302" }] };

export default function ChatWindow({ userId }) {
  const { user, loading } = useAuth();
  const router = useRouter();
  const socket = useSocket();

  const [partner, setPartner] = useState(null);
  const [messages, setMessages] = useState([]);
  const [input, setInput] = useState("");
  const [replyingTo, setReplyingTo] = useState(null);
  const [isTyping, setIsTyping] = useState(false);
  const [showEmojiPicker, setShowEmojiPicker] = useState(false);

  const fileInputRef = useRef();
  const endRef = useRef();
  const typingTimer = useRef();

  // Load profile
  useEffect(() => {
    if (!userId) return;
    api
      .get(`/api/users/profile/${userId}`)
      .then(({ data }) => setPartner(data.user))
      .catch(console.error);
  }, [userId]);

  // Socket setup
  useEffect(() => {
    if (!socket || !user) return;
    socket.emit("join", user.id);

    api
      .get(`/api/messages/${userId}`)
      .then(({ data }) => setMessages(data))
      .catch(console.error);

    socket.on("receive_message", (m) => setMessages((ms) => [...ms, m]));
    socket.on("message_sent", (m) => setMessages((ms) => [...ms, m]));
    socket.on("typing", ({ from }) => from === userId && setIsTyping(true));
    socket.on(
      "stop_typing",
      ({ from }) => from === userId && setIsTyping(false)
    );

    return () => {
      socket.off("receive_message");
      socket.off("message_sent");
      socket.off("typing");
      socket.off("stop_typing");
    };
  }, [socket, user, userId]);

  // Auto‐scroll
  useEffect(() => {
    endRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages]);

  // Send
  const sendChat = () => {
    if (!socket || !input.trim()) return;
    socket.emit("send_message", {
      receiver_id: userId,
      content: input,
      reply_to: replyingTo?.id || null,
    });
    setInput("");
    setReplyingTo(null);
    socket.emit("stop_typing", { to: userId });
  };

  // Typing
  const onType = (e) => {
    setInput(e.target.value);
    socket.emit("typing", { to: userId });
    clearTimeout(typingTimer.current);
    typingTimer.current = setTimeout(
      () => socket.emit("stop_typing", { to: userId }),
      600
    );
  };

  // Delete
  const handleDelete = async (id) => {
    try {
      await api.delete(`/api/messages/${id}`);
      setMessages((ms) => ms.filter((m) => m.id !== id));
    } catch (err) {
      console.error(err);
    }
  };

  // Image
  const pickPhoto = () => fileInputRef.current.click();
  const onPhotoChange = (e) => {
    const file = e.target.files[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = () => setInput(reader.result);
    reader.readAsDataURL(file);
  };

  if (loading || !user || !partner) return null;

  return (
    <div className="flex flex-col w-full h-full bg-white">
      {/* Header */}
      <div className="bg-blue-50 px-4 py-2 font-semibold text-lg">
        {partner.username}
      </div>

      {/* Reply preview */}
      {replyingTo && (
        <div className="px-4 py-2 bg-gray-100 flex justify-between items-center text-sm">
          <span>Reply to: {replyingTo.content}</span>
          <button onClick={() => setReplyingTo(null)}>✖</button>
        </div>
      )}

      {/* Messages */}
      <div className="flex-1 overflow-y-auto px-4 py-2">
        {messages.map((m) => (
          <MessageBubble
            key={m.id}
            msg={m}
            mine={m.sender_id === user.id}
            onDelete={handleDelete}
            onReply={(msg) => setReplyingTo(msg)}
          />
        ))}
        <div ref={endRef} />
      </div>

      {isTyping && (
        <div className="px-4 pb-1 italic text-sm text-gray-500">Typing…</div>
      )}

      {/* Input */}
      <div className="px-4 py-3 bg-white border-t flex items-center space-x-2">
        <button onClick={() => setShowEmojiPicker((v) => !v)}>😀</button>
        <button onClick={pickPhoto}>📷</button>
        <input
          type="file"
          accept="image/*"
          ref={fileInputRef}
          onChange={onPhotoChange}
          className="hidden"
        />
        <input
          type="text"
          value={input}
          onChange={onType}
          onKeyDown={(e) => e.key === "Enter" && sendChat()}
          placeholder="Type a message…"
          className="flex-1 border border-gray-300 px-3 py-2 rounded-full focus:outline-none"
        />
        <button
          onClick={sendChat}
          className="bg-blue-500 text-white px-4 py-2 rounded-full"
        >
          Send
        </button>
      </div>

      {/* Emoji picker */}
      {showEmojiPicker && (
        <div className="grid grid-cols-8 gap-2 bg-blue-50 border-t px-4 py-2 max-h-40 overflow-y-auto">
          {EMOJI_LIST.map((e) => (
            <button
              key={e}
              onClick={() => setInput((i) => i + e)}
              className="text-2xl"
            >
              {e}
            </button>
          ))}
        </div>
      )}
    </div>
  );
}
